using OsEngine.Entity;
namespace OfflineStand;
public static partial class Cases
{
    static void Registry()
    {
        Add("registry","Repeated journal NumberUser appears once in own snapshot",c=>{var f=c.New();f.Tick();f.Ack(f.First,OrderStateType.Active);f.Tab.PositionsAll[0].OpenOrders.Add(f.First);Assert.Equal(1,f.Active().Count);});
        Add("registry","Registry snapshots do not alias mutable journal orders",c=>{var f=c.New();f.Tick();var o=f.First;f.Ack(o,OrderStateType.Active);var snapshot=f.Registry(o.NumberUser);Assert.That(!ReferenceEquals(snapshot,o),"registry aliases journal");o.VolumeExecute=3;Assert.Equal(0m,snapshot.VolumeExecute);});
        Add("registry","Execution quantity is monotonic across stale callbacks",c=>{var f=c.New();f.Tick();var o=f.First;f.Ack(o,OrderStateType.Partial,4);f.Ack(o,OrderStateType.Partial,2);Assert.Equal(4m,f.Registry(o.NumberUser).VolumeExecute);});
        Add("registry","Cancel after Partial preserves actual remaining quantity",c=>{var f=c.New();f.Tick();var o=f.First;f.Ack(o,OrderStateType.Partial,3);f.Off();f.Tick();Assert.Equal(7m,f.Last.Volume);f.Ack(o,OrderStateType.Cancel,3);Assert.Equal(3m,f.Registry(o.NumberUser).VolumeExecute);});
        Add("registry","Late Done after Cancel blocks replacement",c=>{var f=CancelPending(c);var o=f.First;f.Ack(o,OrderStateType.Cancel);f.Ack(o,OrderStateType.Done,10);f.On();f.Tick();Assert.That(f.Error,"late Done not blocked");Assert.Equal(2,f.Count);});
        Add("registry","Same-terminal fill correction before replacement merges and waits balance",c=>{var f=CancelPending(c);var o=f.First;f.Ack(o,OrderStateType.Cancel,2);f.Live();f.Ack(o,OrderStateType.Cancel,3);Assert.That(!f.Error,"valid terminal correction treated as Error");Assert.Equal(3m,f.Registry(o.NumberUser).VolumeExecute);f.Advance(TimeSpan.FromSeconds(1));f.On();f.Tick();Assert.Equal(2,f.Count,"replacement used pre-fill portfolio");});
        Add("registry","Increased terminal fill after replacement fails closed",c=>{var f=CancelPending(c);var o=f.First;f.Ack(o,OrderStateType.Cancel,2);f.On();f.Tick();Assert.Equal(3,f.Count);f.Ack(o,OrderStateType.Cancel,3);Assert.That(f.Error,"post-replacement late fill accepted");});
        Add("registry","Duplicate terminal callback is idempotent",c=>{var f=CancelPending(c);f.Ack(f.First,OrderStateType.Cancel);var initial=(DateTime)Reflect.Get(f.Robot,"_lastTerminalTime");f.Advance(TimeSpan.FromSeconds(2));var shifted=(DateTime)Reflect.Get(f.Robot,"_lastTerminalTime");f.Ack(f.First,OrderStateType.Cancel);Assert.Equal(shifted,(DateTime)Reflect.Get(f.Robot,"_lastTerminalTime"),"duplicate terminal restarted settle");Assert.That(!f.Error,"duplicate terminal caused Error");});
        Add("registry","Unknown event cannot release pending own place",c=>{var f=c.New();f.Tick();var unknown=f.First.Copy();unknown.NumberUser=999;unknown.State=OrderStateType.Active;f.Update(unknown);Assert.That(f.Operation!=null,"unknown ack released own operation");f.Tick();Assert.Equal(1,f.Count);});
        Add("registry","Unrelated Fail event cannot disable this robot",c=>{var f=c.New();f.Update(new(){NumberUser=999,Side=Side.Sell,Price=500,Volume=1,State=OrderStateType.Fail});Assert.That(!f.Error,"foreign Fail disabled robot");f.Tick();Assert.Equal(1,f.Count);});
        Add("registry","Missing nonterminal journal order fails closed",c=>{var f=c.New();f.Tick();f.Ack(f.First,OrderStateType.Active);f.Tab.PositionsAll.Clear();f.Tick();Assert.That(f.Error,"missing order not Error");Assert.Equal(1,f.Count);});
        Add("registry","Null journal with known active order fails closed",c=>{var f=c.New();f.Tick();f.Ack(f.First,OrderStateType.Active);f.Tab.PositionsAll=null;f.Tick();Assert.That(f.Error,"null journal not Error");Assert.Equal(1,f.Count);});
        Add("registry","Unknown live journal order after startup is not adopted",c=>{var f=c.New();f.Tab.PositionsAll.Add(new(){Number=77,OpenOrders=new(){new(){NumberUser=77,Side=Side.Buy,Price=100,Volume=10,State=OrderStateType.Active}}});f.Tick();Assert.That(f.Error,"unknown journal order adopted");Assert.Equal(0,f.Count);});
        Add("registry","Own side mutation fails closed",c=>{var f=c.New();f.Tick();f.Ack(f.First,OrderStateType.Active);var bad=f.First.Copy();bad.Side=Side.Sell;f.Update(bad);Assert.That(f.Error,"side mutation accepted");});
        Add("registry","Own initial-volume mutation fails closed",c=>{var f=c.New();f.Tick();f.Ack(f.First,OrderStateType.Active);var bad=f.First.Copy();bad.Volume=20;f.Update(bad);Assert.That(f.Error,"volume identity mutation accepted");});
        Add("registry","Market identity attaches once and cannot change",c=>{var f=c.New();f.Tick();var o=f.First;o.NumberMarket="market-1";f.Ack(o,OrderStateType.Active);var bad=o.Copy();bad.NumberMarket="market-2";f.Update(bad);Assert.That(f.Error,"market identity mutation accepted");});
        Add("registry","Stale Pending cannot regress known Active and prevent Off cancellation",c=>{var f=c.New();f.Tick();var o=f.First;f.Ack(o,OrderStateType.Active);var stale=o.Copy();stale.State=OrderStateType.Pending;f.Update(stale);f.Off();f.Tick();Assert.Equal(2,f.Count);Assert.Equal("Cancel",f.Last.Kind);});
        Add("registry","Price changes without expected operation fail closed",c=>{var f=c.New();f.Tick();f.Ack(f.First,OrderStateType.Active);var bad=f.First.Copy();bad.Price=99;f.Update(bad);Assert.That(f.Error,"unsolicited price accepted");});
        Add("registry","Post-delete connector and order callbacks leave state unchanged",c=>{var f=c.New();f.Tick();var o=f.First.Copy();long before=(long)Reflect.Get(f.Robot,"_eventNumber");f.Dispose();o.State=OrderStateType.Fail;f.Tab.Update(o);f.Tab.Connector.Emit(o);Assert.Equal(before,(long)Reflect.Get(f.Robot,"_eventNumber"));Assert.That(!f.Error,"deleted robot processed callback");});
        Add("registry","Journal terminal without callback starts live settle barrier",c=>{var f=c.New();f.Tick();f.Ack(f.First,OrderStateType.Active);f.Live();f.First.State=OrderStateType.Done;f.First.VolumeExecute=10;f.Tick();Assert.Equal(1,f.Count);Assert.Equal(10m,f.Registry(f.First.NumberUser).VolumeExecute);});
        Add("registry","Raw cancel fill reconciles journal callback which arrived first",c=>{var f=c.New();f.Tick();var o=f.First;f.Ack(o,OrderStateType.Active);f.Off();f.Tick();var journal=o.Copy();journal.State=OrderStateType.Cancel;journal.VolumeExecute=0;f.Update(journal);var raw=journal.Copy();raw.VolumeExecute=3;f.RawOrder(raw);Assert.That(!f.Error,"authoritative raw cancel fill treated as late unexpected fill");Assert.Equal(3m,f.Registry(o.NumberUser).VolumeExecute);});
        Add("registry","Raw Partial fill survives stale journal quantity",c=>{var f=c.New();f.Tick();var o=f.First;f.Ack(o,OrderStateType.Active);var raw=o.Copy();raw.State=OrderStateType.Partial;raw.VolumeExecute=3;f.RawOrder(raw);var journal=o.Copy();journal.State=OrderStateType.Partial;journal.VolumeExecute=0;f.Update(journal);Assert.Equal(3m,f.Registry(o.NumberUser).VolumeExecute);});
    }
}

